  ('Enfermería', 4, 'Psicología del Desarrollo', 1, 'Diagnóstico diferencial ante sintomatología patológica compleja'),
  ('Enfermería', 4, 'Psicología del Desarrollo', 2, 'Selección del esquema terapéutico e intervención médica/enfermería')
) as v(carrera, semestre, materia, orden, tema)
join carreras c           on c.nombre = v.carrera
join semestres_carrera s  on s.carrera_id = c.id and s.numero = v.semestre
join materias_carrera m   on m.semestre_id = s.id and m.nombre = v.materia
on conflict (materia_id, orden) do nothing;
